public class Main {
public static void main(String[] args) throws Exception {
final ConcurrentStack<Integer> stack = new ConcurrentStack<Integer>();
ExecutorService es = Executors.newFixedThreadPool(3);
for (int i = 0; i < 3; i++) {
final int base = i * 10;
es.execute(() -> {
for (int j = 0; j < 10; j++) {
stack.push(base + j);
System.out.println("Pushed " + (base + j));
}
for (int j = 0; j < 10; j++) {
Integer v = stack.pop();
System.out.println("Popped " + v);
}
});
