public class BarrierTimer implements Runnable {
private boolean started;
private long startTime;
private long endTime;

public synchronized void run() {
long now = System.nanoTime();
if (!started) {
started = true;
startTime = now;
} else {
endTime = now;
}
}

public synchronized void clear() {
started = false;
}

public synchronized long getTime() {
return endTime - startTime;
}

public static void main(String[] args) {
final BarrierTimer timer = new BarrierTimer();
ExecutorService executor = Executors.newFixedThreadPool(2);
executor.submit(() -> {
timer.run();
});
executor.submit(() -> {
timer.run();
});
executor.shutdown();
try {
executor.awaitTermination(5, TimeUnit.SECONDS);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
System.out.println("Elapsed: " + timer.getTime());
timer.clear();
}
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CasCounter {
private final SimulatedCAS cas = new SimulatedCAS();

public int getValue() {
return cas.get();
}

public int increment() {
int oldValue;
do {
oldValue = cas.get();
} while (cas.compareAndSwap(oldValue, oldValue + 1) != oldValue);
return oldValue + 1;
}

static class SimulatedCAS {
private int value;

public synchronized int get() {
return value;
}

public synchronized int compareAndSwap(int expectedValue, int newValue) {
int oldValue = value;
if (oldValue == expectedValue) {
value = newValue;
}
return oldValue;
}
}

public static void main(String[] args) {
final CasCounter counter = new CasCounter();
ExecutorService executor = Executors.newFixedThreadPool(2);
executor.submit(() -> {
counter.increment();
});
executor.submit(() -> {
counter.increment();
});
executor.shutdown();
try {
executor.awaitTermination(5, TimeUnit.SECONDS);
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
System.out.println("Value: " + counter.getValue());
}
}
